-- ANIMAUX'26 update: Shutter Safari photography rules (online/offline, up to 3 photos). Registrations are not touched. Safe to run more than once.
update public.events
set event_date = '2026-12-02', start_time = '', end_time = '15:00',
    deadline = '2026-12-02T15:00:00+05:30', capacity = null,
    short_description = 'Capture wildlife, nature and survival through your lens — upload up to 3 photos when you register, or bring A4 prints on the day.',
    eligibility = 'Individual participants. One registration per person, with up to 3 photos (online upload or A4 prints at the venue). No limit on participants.',
    rules = '["# Registration","Registration is open until the fest day — it closes at 3:00 PM on 2 December 2026. Late entries won’t be accepted.","Offline participants (printed photos) must also register online by this deadline.","One registration per participant. Show your registration confirmation (ID) when you submit.","No limit on the number of participants.","# Theme","Photos must reflect Echoes of the Wild: The Survival Files, showing wildlife, nature, struggle, adaptation or survival.","A short caption (max 30 words) explaining how the photo fits the theme is required.","# Submission: online","Upload in JPEG/PNG format, minimum 3000 px on the longer side, under 10 MB.","File name format: Name_Title.jpg.","Maximum 3 entries per participant.","# Submission: offline","Photos must be printed on A4 size paper (21 × 29.7 cm), glossy or matte.","Write your name, contact number, photo title and location on the back, not on the front.","No frames, borders or mounts. Prints should be flat and undamaged.","Maximum 3 prints per participant, submitted at the venue desk by 3:00 PM on 2 December.","# Originality and editing","Photos must be taken by the participant and be original work.","Basic edits (crop, exposure, contrast, colour correction) are allowed.","Not allowed: AI-generated images, composites, added or removed subjects, heavy filters, or watermarks and signatures on the image.","Organisers may request the original RAW/unedited file for verification.","# Ethics","No harm, baiting or disturbance to wildlife or habitats for a shot. Photos showing cruelty will be disqualified.","Captive or staged animals must be declared; they are not eligible for the main category.","# Judging","Judging criteria: theme relevance (30%), storytelling (25%), composition (20%), technical quality (15%), originality (10%).","The judges’ decision is final and binding.","# General","Organisers may display or use submitted photos for promotion, with credit given to the photographer. Copyright remains with the participant.","Violating any rule results in disqualification."]'::jsonb,
    extra_questions = '[{"id":"mode","label":"How will you submit your photos?","type":"select","options":["Online — upload my photos here","Offline — printed A4 photos at the venue desk"],"required":true,"help":"Offline: bring up to 3 A4 prints to the venue desk by 3:00 PM on 2 December."},{"id":"photo","label":"Photo 1","type":"file","minLongSide":3000,"onlyWhen":{"id":"mode","equals":"Online — upload my photos here"},"required":true,"help":"JPEG or PNG · at least 3000 px on the longer side · under 10 MB. Name the file Name_Title.jpg."},{"id":"title","label":"Photo 1 — title","type":"text","onlyWhen":{"id":"mode","equals":"Online — upload my photos here"},"required":true},{"id":"caption","label":"Photo 1 — caption: how does it fit the theme? (max 30 words)","type":"textarea","maxWords":30,"onlyWhen":{"id":"mode","equals":"Online — upload my photos here"},"required":true},{"id":"photo2","label":"Photo 2 (optional)","type":"file","minLongSide":3000,"onlyWhen":{"id":"mode","equals":"Online — upload my photos here"}},{"id":"title2","label":"Photo 2 — title","type":"text","onlyWhen":{"id":"mode","equals":"Online — upload my photos here"},"requiredWith":"photo2"},{"id":"caption2","label":"Photo 2 — caption: how does it fit the theme? (max 30 words)","type":"textarea","maxWords":30,"onlyWhen":{"id":"mode","equals":"Online — upload my photos here"},"requiredWith":"photo2"},{"id":"photo3","label":"Photo 3 (optional)","type":"file","minLongSide":3000,"onlyWhen":{"id":"mode","equals":"Online — upload my photos here"}},{"id":"title3","label":"Photo 3 — title","type":"text","onlyWhen":{"id":"mode","equals":"Online — upload my photos here"},"requiredWith":"photo3"},{"id":"caption3","label":"Photo 3 — caption: how does it fit the theme? (max 30 words)","type":"textarea","maxWords":30,"onlyWhen":{"id":"mode","equals":"Online — upload my photos here"},"requiredWith":"photo3"}]'::jsonb
where slug = 'shutter-safari';

update public.faqs set question = 'How do I submit my photos for Shutter Safari?', answer = 'Register by 3:00 PM on 2 December and choose online or offline. Online: upload up to 3 photos (JPEG/PNG, at least 3000 px on the longer side, under 10 MB), each with a title and a caption of up to 30 words. Offline: bring up to 3 A4 prints to the venue desk by 3:00 PM on 2 December, with your name, contact number, photo title and location written on the back. Full rules are on the Shutter Safari page.' where id = 'fa000000-0000-4000-8000-000000000007';
